		[515]={ skill_id=103280, skill_levelup_data={
		[4537]={ skill_lv=1, hero_rank=0, cost_item={}, need_star=0, pay_tid=0, pay_num=0, desc="自身在场时，每回合开始将激活<color=#ffb136>旋风场</color>——友方所有战员攻击提升<color=#18ec68>10</color>%；同属性战员行动时，攻击额外提升聆风攻击的<color=#18ec68>6</color>%,最多叠加2层，持续1回合；自身在<color=#ffb136>旋风场</color>中无视防御提升<color=#18ec68>16</color>%", skill_levelup_des="" },
